import{_ as p,r as t,o as r,c,e as s,a as e,s as o,d as a}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Developing Themes - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Theme Information File","slug":"theme-information-file","link":"#theme-information-file","children":[]},{"level":2,"title":"Version File","slug":"version-file","link":"#version-file","children":[]},{"level":2,"title":"Theme Preview Image","slug":"theme-preview-image","link":"#theme-preview-image","children":[]},{"level":2,"title":"Theme Dependencies","slug":"theme-dependencies","link":"#theme-dependencies","children":[]},{"level":2,"title":"Theme Customization","slug":"theme-customization","link":"#theme-customization","children":[{"level":3,"title":"Using Theme Data In CSS","slug":"using-theme-data-in-css","link":"#using-theme-data-in-css","children":[]}]},{"level":2,"title":"Localization","slug":"localization","link":"#localization","children":[{"level":3,"title":"Localization File Structure","slug":"localization-file-structure","link":"#localization-file-structure","children":[]}]}],"relativePath":"2.x/themes/development.md","filePath":"2.x/themes/development.md"}'),u={name:"2.x/themes/development.md"};function d(h,n,m,g,k,f){const l=t("pre-heading"),i=t("post-heading");return r(),c("div",null,[s(l),n[0]||(n[0]=e("h1",null,"Developing Themes",-1)),s(i),n[1]||(n[1]=o(`<p>The theme directory could include the <strong>theme.yaml</strong>, <strong>version.yaml</strong> and <strong>assets/images/theme-preview.png</strong> files. These files are optional for the local development but required for themes published on the October CMS Marketplace.</p><p><a id="oc-theme-information-file"></a></p><h2 id="theme-information-file"><a href="#theme-information-file" class="header-anchor">#</a> Theme Information File</h2><p>The theme information file <strong>theme.yaml</strong> contains the theme description, the author name, URL of the author&#39;s website and some other information. The file should be placed to the theme root directory:</p><pre class="dir-container"><code><p>├── themes
|   └── website
|       ├── pages
|       ├── layouts
|       ├── partials
|       ├── content
|       ├── assets
|       └── <code>theme.yaml</code> <em>&lt;== Information File</em></p>
</code></pre><p>The following fields are supported in the <strong>theme.yaml</strong> file:</p><div class="table"><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>name</strong></td><td>specifies the theme name, required.</td></tr><tr><td><strong>author</strong></td><td>specifies the author name, required.</td></tr><tr><td><strong>homepage</strong></td><td>specifies the author website URL, required.</td></tr><tr><td><strong>description</strong></td><td>the theme description, required.</td></tr><tr><td><strong>previewImage</strong></td><td>custom preview image, path relative to the theme directory, eg: <code>assets/images/preview.png</code>, optional.</td></tr><tr><td><strong>code</strong></td><td>the theme code, optional. The value is used on the October CMS marketplace for initializing the theme code value.</td></tr><tr><td><strong>authorCode</strong></td><td>the theme author code, optional. The value is used on the October CMS marketplace for defining the theme owner.</td></tr><tr><td><strong>form</strong></td><td>a configuration array or reference to a form field definition file, used for <a href="#oc-theme-customization">theme customization</a>, optional.</td></tr><tr><td><strong>require</strong></td><td>an array of plugin names used for <a href="#oc-theme-dependencies">theme dependencies</a>, optional.</td></tr></tbody></table></div><p>Example of the theme information file:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">name</span><span class="token punctuation">:</span> <span class="token string">&quot;October CMS Demo&quot;</span>
<span class="token key atrule">description</span><span class="token punctuation">:</span> <span class="token string">&quot;Demonstrates the basic concepts of the front-end theming.&quot;</span>
<span class="token key atrule">author</span><span class="token punctuation">:</span> <span class="token string">&quot;October CMS&quot;</span>
<span class="token key atrule">homepage</span><span class="token punctuation">:</span> <span class="token string">&quot;https://octobercms.com&quot;</span>
<span class="token key atrule">code</span><span class="token punctuation">:</span> <span class="token string">&quot;Demo&quot;</span>
<span class="token key atrule">authorCode</span><span class="token punctuation">:</span> <span class="token string">&quot;Acme&quot;</span>
</code></pre></div><p><a id="oc-version-file"></a></p><h2 id="version-file"><a href="#version-file" class="header-anchor">#</a> Version File</h2><p>The theme version file <strong>version.yaml</strong> defines the current theme version and the change log. The file should be placed to the theme root directory.</p><pre class="dir-container"><code><p>├── themes
|   └── website
|       ├── ...
|       └── theme.yaml
|       └── <code>version.yaml</code> <em>&lt;== Version File</em></p>
</code></pre><p>The file contains the following format.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">v1.0.1</span><span class="token punctuation">:</span> Theme initialization
<span class="token key atrule">v1.0.2</span><span class="token punctuation">:</span> Added more features
<span class="token key atrule">v1.0.3</span><span class="token punctuation">:</span> Some features are removed
</code></pre></div><h2 id="theme-preview-image"><a href="#theme-preview-image" class="header-anchor">#</a> Theme Preview Image</h2><p>The theme preview image is used in the back-end theme selector. The image file <strong>theme-preview.png</strong> should be placed to the theme&#39;s <strong>assets/images</strong> directory:</p><pre class="dir-container"><code><p>├── themes
|   └── website
|       ├── ...
|       └── assets
|           └── images
|               └── <code>theme-preview.png</code> <em>&lt;== Preview Image</em></p>
</code></pre><p>The image width should be at least 600px. The ideal aspect ratio is 1.5, for example 600x400px.</p><h2 id="theme-dependencies"><a href="#theme-dependencies" class="header-anchor">#</a> Theme Dependencies</h2><p>A theme can depend on plugins by defining a <strong>require</strong> option in the <a href="#theme-information-file">Theme information file</a>, the option should supply an array of plugin names that are considered requirements. A theme that depends on <strong>Acme.Blog</strong> and <strong>Acme.User</strong> can define this requirement like so:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">name</span><span class="token punctuation">:</span> <span class="token string">&quot;October CMS Demo&quot;</span>
<span class="token comment"># [...]</span>

<span class="token key atrule">require</span><span class="token punctuation">:</span>
    <span class="token punctuation">-</span> <span class="token string">&quot;Acme.User&quot;</span>
    <span class="token punctuation">-</span> <span class="token string">&quot;Acme.Blog&quot;</span>
</code></pre></div><p>When the theme is installed for the first time, the system will attempt to install the required plugins at the same time. For a streamlined experience, consider <a href="./../help/publishing-packages.html#declaring-dependencies">adding these plugins to the composer depedency list</a> as well.</p><p><a id="oc-theme-customization"></a></p><h2 id="theme-customization"><a href="#theme-customization" class="header-anchor">#</a> Theme Customization</h2><p>Themes can support configuration values by defining a <code>form</code> key in the theme information file. This key should contain a configuration array or reference to a form field definition file, see <a href="./../backend/forms.html#oc-defining-form-fields">form fields</a> for more information.</p><p>The following is an example of how to define a website name configuration field called <strong>site_name</strong>:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">name</span><span class="token punctuation">:</span> My Theme
<span class="token comment"># [...]</span>

<span class="token key atrule">form</span><span class="token punctuation">:</span>
    <span class="token key atrule">fields</span><span class="token punctuation">:</span>
        <span class="token key atrule">site_name</span><span class="token punctuation">:</span>
            <span class="token key atrule">label</span><span class="token punctuation">:</span> Site name
            <span class="token key atrule">comment</span><span class="token punctuation">:</span> The website name as it should appear on the front<span class="token punctuation">-</span>end
            <span class="token key atrule">default</span><span class="token punctuation">:</span> My Amazing Site<span class="token tag">!</span>
</code></pre></div><p>The value can then be accessed inside any of the Theme templates using the <a href="./../markup/this-theme.html">global Twig variable</a> called <code>this.theme</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Welcome to <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> this<span class="token punctuation">.</span>theme<span class="token punctuation">.</span>site_name <span class="token delimiter punctuation">}}</span></span>!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>You may also define the configuration in a separate file, where the path is relative to the theme. The following definition will source the form fields from the file <strong>config/fields.yaml</strong> inside the theme.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">name</span><span class="token punctuation">:</span> My Theme
<span class="token comment"># [...]</span>

<span class="token key atrule">form</span><span class="token punctuation">:</span> config/fields.yaml
</code></pre></div><p><strong>themes/demo/config/fields.yaml</strong>:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">site_name</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Site name
        <span class="token key atrule">comment</span><span class="token punctuation">:</span> The website name as it should appear on the front<span class="token punctuation">-</span>end
        <span class="token key atrule">default</span><span class="token punctuation">:</span> My Amazing Site<span class="token tag">!</span>
</code></pre></div><h3 id="using-theme-data-in-css"><a href="#using-theme-data-in-css" class="header-anchor">#</a> Using Theme Data In CSS</h3><p>Sometimes you want to include a visual preference inside your theme stylesheet. You may use CSS custom properties (variables) to make these values available. In the following example, we will use a <a href="./../backend/forms.html#widget-colorpicker">Color Picker field type</a> to specify a custom link color.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">form</span><span class="token punctuation">:</span>
    <span class="token key atrule">fields</span><span class="token punctuation">:</span>
        <span class="token comment"># [...]</span>

        <span class="token key atrule">link_color</span><span class="token punctuation">:</span>
            <span class="token key atrule">label</span><span class="token punctuation">:</span> Link color
            <span class="token key atrule">type</span><span class="token punctuation">:</span> colorpicker
</code></pre></div><p>Using the above example we can define a <a href="./../cms/partials.html">CMS partial</a> that passes the selected value to CSS using a local stylesheet. The partial is then included in the <a href="./../cms/layouts.html">theme layout</a> inside the <code>&lt;head&gt;</code> tag.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>style</span><span class="token punctuation">&gt;</span></span><span class="token style"><span class="token language-css">
    <span class="token selector">:root</span> <span class="token punctuation">{</span>
        <span class="token selector">--my-color:</span> <span class="token punctuation">{</span><span class="token punctuation">{</span> this.theme.link_color <span class="token punctuation">}</span><span class="token punctuation">}</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>style</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><blockquote><p><strong>Note</strong>: Custom property names are case sensitive so <code>--my-color</code> will be treated as a separate custom property to <code>--My-color</code>.</p></blockquote><p>Now inside your stylesheet the custom property can be used anywhere by specifying the custom property name inside the <code>var()</code> function, in place of a regular property value.</p><div class="language-css extra-class"><pre class="language-css"><code><span class="token selector">a</span> <span class="token punctuation">{</span>
    <span class="token property">color</span><span class="token punctuation">:</span> <span class="token function">var</span><span class="token punctuation">(</span>--my-color<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="localization"><a href="#localization" class="header-anchor">#</a> Localization</h2><p>Themes can provide backend localization keys through files placed in the <strong>lang</strong> subdirectory of the theme&#39;s directory. These localization keys are registered automatically only when interacting with the October backend and can be used for form labels just like <a href="./../plugin/localization.html">plugin localization</a></p>`,44)),n[2]||(n[2]=e("blockquote",null,[e("p",null,[e("strong",null,"Note"),a(": Translating frontend content should be handled with the "),e("a",{href:"https://octobercms.com/plugin/rainlab-translate",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("RainLab.Translate"),e("span",null,[e("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[e("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),e("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),e("span",{class:"sr-only"},"(opens new window)")])]),a(" plugin.")])],-1)),n[3]||(n[3]=o(`<h3 id="localization-file-structure"><a href="#localization-file-structure" class="header-anchor">#</a> Localization File Structure</h3><p>Below is an example of the theme&#39;s language directory.</p><pre class="dir-container"><code><p>├── themes
|   └── website
|       └── <code>lang</code> <em>&lt;== Localization Directory</em>
|           ├── en
|           |   └── lang.php <em>&lt;== Localization File</em>
|           └── fr
|               └── lang.php</p>
</code></pre><p>The <strong>lang.php</strong> file should define and return an array of any depth, for example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;options&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;website_name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;October CMS&#39;</span>
    <span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>You are then able to reference the keys using <code>theme.theme-code::lang.key</code>. In the above example, the full language key you would use to reference the &quot;website_name&quot; localization key would be <code>theme.acme::lang.options.website_name</code>.</p>`,6))])}const b=p(u,[["render",d]]);export{v as __pageData,b as default};
